    const reactionEntry=document.querySelector('.reaction-entry');if(reactionEntry){document.querySelector('.nav-scroll').prepend(reactionEntry);}
    bindNav();$('.menu-toggle').addEventListener('click',()=>{const open=$('.sidebar').classList.toggle('open');$('.mobile-overlay').classList.toggle('open',open);$('.menu-toggle').setAttribute('aria-expanded',String(open));});$('.mobile-overlay').addEventListener('click',closeMenu);
